import pandas as pd, numpy as np, networkx as nx
from shapely import wkb
from shapely.geometry import Point
nodes = pd.read_parquet('/bench/fixtures/town_nodes.parquet')
edges = pd.read_parquet('/bench/fixtures/town_edges.parquet')
pois = pd.read_parquet('/bench/fixtures/town_pois.parquet')
edges['ln'] = edges.geometry.apply(wkb.loads)
pois['pt'] = pois.geometry.apply(wkb.loads)
nd = {r.node_id:wkb.loads(r.geometry) for r in nodes.itertuples()}
o = Point(0.0027219,0.0027493)
speed=1.33; T=900; LIM=T*speed  # metres
def run(snap_mode):
    # snap_mode 'edge': split edges at projections; 'node': nearest node
    G=nx.DiGraph()
    def addE(a,b,w):
        if G.has_edge(a,b): G[a][b]['w']=min(G[a][b]['w'],w)
        else: G.add_edge(a,b,w=w)
    splits={}  # edge_id -> list of (dist_frac, label)
    def proj_frac(line, pt):
        return line.project(pt, normalized=True)
    # origin
    ext = {}
    if snap_mode=='edge':
        e = edges.iloc[min(range(len(edges)), key=lambda i: edges.ln.iloc[i].distance(o))]
        oe_id = e.edge_id; f = proj_frac(e.ln, o)
        splits.setdefault(oe_id,[]).append((f,'ORIGIN'))
        origin_node=None
    else:
        origin_node = min(nd, key=lambda k: nd[k].distance(o))
    poi_loc={}
    for r in pois.itertuples():
        if snap_mode=='edge':
            i = min(range(len(edges)), key=lambda i: edges.ln.iloc[i].distance(r.pt))
            eid=edges.edge_id.iloc[i]; f=proj_frac(edges.ln.iloc[i], r.pt)
            splits.setdefault(eid,[]).append((f,r.poi_id)); poi_loc[r.poi_id]=('edge',eid)
        else:
            poi_loc[r.poi_id]=('node', min(nd, key=lambda k: nd[k].distance(r.pt)))
    # build graph
    for r in edges.itertuples():
        L=float(r.length_m); u,v=r.u,r.v
        pts=[(0.0,u)]
        for f,lab in sorted(splits.get(r.edge_id,[])):
            pts.append((f,('X',lab)))
        pts.append((1.0,v))
        pts.sort(key=lambda x:x[0])
        for (f1,n1),(f2,n2) in zip(pts[:-1],pts[1:]):
            w=(f2-f1)*L
            addE(n1,n2,w)
            if not r.oneway: addE(n2,n1,w)
    # origin
    if snap_mode=='edge':
        src=('X','ORIGIN')
    else:
        src=origin_node
    d=nx.single_source_dijkstra_path_length(G,src,weight='w',cutoff=LIM+1e-9)
    res=[]
    for r in pois.itertuples():
        if r.amenity_category!='grocery': continue
        kind,ref=poi_loc[r.poi_id]
        if kind=='node': dd=d.get(ref,np.inf)
        else: dd=d.get(('X',r.poi_id),np.inf)
        res.append((r.poi_id, round(dd/speed,3) if np.isfinite(dd) else None, dd<=LIM))
    return res
