    G.add_edge(e.u,e.v,w=e.length_m)
    if not e.oneway: G.add_edge(e.v,e.u,w=e.length_m)
def snap(px,py):
    P=scale(px,py); best=None
    for e in edges.itertuples():
        c=[scale(*xy) for xy in e.geometry.coords]
        a,b=c[0],c[-1]; ab=b-a
        t=np.dot(P-a,ab)/np.dot(ab,ab); t=min(max(t,0),1)
        d=np.linalg.norm(P-(a+t*ab))
        if best is None or d<best[0]: best=(d,e.edge_id,e.u,e.v,t,e.length_m,bool(e.oneway))
    return dict(dist_m=best[0],eid=best[1],u=best[2],v=best[3],t=best[4],L=best[5],oneway=best[6])
def net_from(s):
    # seeds: node -> cost
    seeds={}
    if (s['u'],s['v']) and True:
        # from point, can reach v (always along u->v direction) at (1-t)L ; reach u at tL if not oneway
        seeds[s['v']]=min(seeds.get(s['v'],1e18),(1-s['t'])*s['L'])
        if not s['oneway']:
            seeds[s['u']]=min(seeds.get(s['u'],1e18),s['t']*s['L'])
    dist=nx.multi_source_dijkstra_path_length(G,seeds,weight='w') if False else None
    # manual multi-source: add super source
    H=G.copy()
    for n,c in seeds.items(): H.add_edge('SRC',n,w=c)
    d=nx.single_source_dijkstra_path_length(H,'SRC',weight='w')
    return d
def dest_cost(d,s):
    # travel to point on edge s from network distances
    opts=[]
    # arrive from u: traverse u->v; allowed always if not oneway or oneway(u->v)
    if s['u'] in d: opts.append(d[s['u']]+s['t']*s['L'])  # fine for u->v direction (edges are u->v)
    if (not s['oneway']) and s['v'] in d: opts.append(d[s['v']]+(1-s['t'])*s['L'])
    return min(opts) if opts else np.inf
